    closing_brackets = 0
    for bracket in brackets:
        if bracket == "<":
            opening_brackets += 1
        elif bracket == ">":
            closing_brackets += 1

    if opening_brackets != closing_brackets:
        return False

    nesting_level = 0
    for bracket in brackets:
